// Primary template for processing pointers
template<typename T>
void processPointer(T* ptr);

// Explicitly delete the specialization for void*
template<>
void processPointer<void>(void*) = delete;

// Explicitly delete the specialization for char*
template<>
void processPointer<char>(char*) = delete;

// Also delete const versions to be thorough
template<>
void processPointer<const void>(const void*) = delete;

template<>
void processPointer<const char>(const char*) = delete;
